  ('43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$Natuurkunde$$, $$HAVO$$, $$Kitmarker$$, $$HAVO Natuurkunde 2021-I$$),
  ('bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$Natuurkunde$$, $$HAVO$$, $$Sprong van Luke Aikins$$, $$HAVO Natuurkunde 2021-I$$),
  ('18aaa64f-6011-4a2e-972d-712bc180dfaa', $$Natuurkunde$$, $$HAVO$$, $$Cicaden$$, $$HAVO Natuurkunde 2021-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('ce79ebb0-59c2-40cb-8f8f-25967432c046', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 1 — tabel stofeigenschappen ijzer (dichtheid, elasticiteitsmodulus, smeltpunt, soortelijke warmte, soortelijke weerstand, treksterkte, warmtegeleidingscoëfficiënt)$$, $$natuurkunde-havo-2021-i-lassen-context1.png$$, 501, $$Voor deze opgave moet je gebruikmaken van de tabel met stofeigenschappen van ijzer in figuur 1.

figuur 1: tabel met stofeigenschappen van ijzer — dichtheid 7,87·10³ kg m⁻³; elasticiteitsmodulus 2,20·10¹¹ Pa; smeltpunt 1,811·10³ K; soortelijke warmte 0,46·10³ J kg⁻¹ K⁻¹; soortelijke weerstand 1,05·10⁻⁷ Ω m; treksterkte 3,5·10⁸ Pa; warmtegeleidingscoëfficiënt 80,3 W m⁻¹ K⁻¹.$$, 'inline'),
  ('4eebc875-a8f0-49cc-b8a3-01ed7639b43d', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 2 — foto van het lassen met een brander$$, $$natuurkunde-havo-2021-i-lassen-context2.png$$, 501, $$Lassen is een techniek om metalen delen aan elkaar te bevestigen. Dit kan door die delen met een brander zo te verhitten dat op de plek van de verhitting het materiaal van beide delen smelt en vervolgens na afkoeling tot één geheel samen vast wordt. Zie figuur 2. Deze plek wordt een ''las'' genoemd.

figuur 2: foto van het lassen van een metalen buis met een brander.$$, 'inline'),
  ('d49edd84-4f0d-4f44-aa82-d8aa930ce668', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 3, 4a en 4b — puntlasapparaat: dikte 1,8 mm, oppervlakte A = 6,4·10⁻⁵ m², spanning 0,20 V, stroomsterkte 68 kA$$, $$natuurkunde-havo-2021-i-lassen-context3.png$$, 501, $$Het smeltpunt kan ook bereikt worden door een elektrische stroom door de metalen delen te laten lopen. Hiervoor wordt een puntlasapparaat gebruikt. Een puntlasapparaat levert een hoge stroomsterkte bij een lage spanning over twee elektroden. Twee plaatjes ijzer worden met een puntlasapparaat aan elkaar gelast. Zie figuur 3. De plaatjes worden op elkaar gelegd en krachtig op elkaar gedrukt door de twee elektroden.

figuur 3: foto van een puntlasapparaat met twee elektroden die een plaatje vasthouden.

Als de elektroden tegen de plaatjes worden gedrukt gaat er een stroom I door het ijzer tussen de elektroden lopen. Het ijzer tussen de elektroden is bij benadering cilindervormig. Zie figuur 4a. De ijzeren plaatjes tussen de elektroden zijn samen 1,8 mm dik en raken elkaar alleen tussen de elektroden. De oppervlakte A waarmee de ijzeren plaatjes elkaar raken, is 6,4·10⁻⁵ m²; deze is even groot als de oppervlakte van de punt van een elektrode. Zie figuur 4a en 4b.

figuur 4a: schema van twee elektroden (spanning 0,20 V) die een cilindervormig stukje ijzer (dikte 1,8 mm, oppervlakte A) tussen twee platen vasthouden.
figuur 4b: detailtekening van elektrode, ijzeren plaat, luchtspouw en gesmolten ijzer bij de punt van de elektrode.

Over de plaatjes staat een spanning van 0,20 V. De stroomsterkte door het ijzer is op dat moment gelijk aan 68 kA.$$, 'inline'),
  ('19948820-8fe2-4489-89c6-a68c49e5f3ff', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$massa cilindervormig ijzer 9,1·10⁻⁴ kg, begintemperatuur 20 °C, 15% van de warmte verhit het ijzer, weerstand constant$$, $$natuurkunde-havo-2021-i-lassen-context4.png$$, 501, $$De massa van het cilindervormige deel ijzer tussen de elektroden is 9,1·10⁻⁴ kg. Het ijzer heeft een begintemperatuur van 20 °C. Van de warmte die ontstaat tussen de elektroden wordt 15% gebruikt om het ijzer tussen de elektroden tot het smeltpunt te verhitten. De weerstand van het ijzer tussen de elektroden wordt als constant beschouwd.$$, 'inline'),
  ('ee887aa0-4d0f-4f2c-b098-6c73625b3efa', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 5 en 6 — meerdere lassen naast elkaar, gelijke spanning per las$$, $$natuurkunde-havo-2021-i-lassen-context5.png$$, 501, $$Vaak worden meerdere lassen naast elkaar gemaakt. Zie figuur 5 en schematisch in figuur 6. De elektrische spanning over de elektroden is voor iedere las even groot.

figuur 5: foto van een metalen strip met meerdere puntlassen naast elkaar, gemaakt met een puntlasapparaat.
figuur 6: schema van een elektrode die vier lassen (donkere stippen) naast elkaar op een metalen strip vastzet, met luchtspouw tussen de platen.

De platen raken elkaar alleen op de lassen. Zie figuur 6.$$, 'inline'),
  ('12704cc5-72da-47d3-bdd6-0e9aebaaa6b4', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 7 — (R,lastijd)-diagram: weerstand ijzer neemt toe tijdens het lassen$$, $$natuurkunde-havo-2021-i-lassen-context6.png$$, 501, $$In werkelijkheid blijft de weerstand van het ijzer tussen de elektroden niet constant gedurende het vormen van een las (de ''lastijd''). Zie figuur 7.

figuur 7: grafiek van de weerstand R tegen de lastijd; de weerstand neemt toe en buigt af naar een maximum (verzadiging).$$, 'inline'),
  ('61c0d108-6a01-47dd-b397-c1252321d29b', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 8 — foto van waterkoeling van de koperen elektroden$$, $$natuurkunde-havo-2021-i-lassen-context7.png$$, 501, $$De koperen elektroden worden heet tijdens het lassen. Ze moeten daarom gekoeld worden door er met slangen water doorheen te pompen. Zie figuur 8.

figuur 8: foto van een puntlasapparaat met koelslangen aangesloten op de elektroden.

Op de uitwerkbijlage staan drie stellingen over het heet worden van de elektroden.$$, 'inline'),
  ('5efd9307-174f-4669-9144-100c23451139', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$figuur 9 — afgekoelde las met trekkracht F, oppervlakte A = 6,4·10⁻⁵ m²$$, $$natuurkunde-havo-2021-i-lassen-context8.png$$, 501, $$Als de las is afgekoeld zijn de ijzeren plaatjes op die plek tot één geheel met elkaar verbonden. De oppervlakte A van de las is 6,4·10⁻⁵ m². Op de las kan een trekkracht F uitgeoefend worden. Zie figuur 9.

figuur 9: schema van twee op elkaar liggende platen met een las (oppervlakte A) waarop een trekkracht F loodrecht op het lasvlak wordt uitgeoefend.$$, 'inline'),
  ('06368360-9999-4788-8747-6dc1adc7fb54', 'cd66d499-9041-43a3-94d7-bfe4b67583d7', $$uitwerkbijlage vraag 6 — tabel met drie stellingen over het heet worden van de elektroden (waar/niet waar)$$, $$natuurkunde-havo-2021-i-lassen-uitwerkbijlage-vraag6.png$$, 501, $$Uitwerkbijlage vraag 6: tabel ''Het heet worden van de elektroden wordt veroorzaakt door:'' met de stellingen ''het hoge smeltpunt van het koper van de elektroden'', ''de elektrische weerstand van de koperen elektroden'' en ''de grote kracht die de elektroden uitoefenen op de ijzeren platen'', elk met aankruisvakjes ''waar'' en ''niet waar''.$$, 'uitwerkbijlage'),
  ('2f77eaec-2582-44f3-8ad9-f60fb84ff006', '594a24dd-c80b-44f7-8939-652805725c80', $$figuur 1 — Jupiter met manen Io, Europa en Ganymedes (niet op schaal)$$, $$natuurkunde-havo-2021-i-de-maan-europa-context1.png$$, 501, $$De planeet Jupiter heeft meerdere manen. Zie figuur 1. Deze figuur is niet op schaal. Een van deze manen heet Europa. Gegevens over de maan Europa zijn te vinden in Binas-tabel 31 of Sciencedata-tabel 3.3a.

figuur 1: schema van Jupiter met daaromheen de banen van de manen Io, Europa en Ganymedes.$$, 'inline'),
  ('f07ec1d5-3595-4964-ae40-8b8f7f88db07', '594a24dd-c80b-44f7-8939-652805725c80', $$straal van de baan van Europa: 670,9·10⁶ m$$, $$natuurkunde-havo-2021-i-de-maan-europa-context2.png$$, 501, $$De straal van de baan van Europa is 670,9·10⁶ m.$$, 'inline'),
  ('a797c423-a3c8-4f55-8cfc-4150bb9ea51c', '594a24dd-c80b-44f7-8939-652805725c80', $$oppervlaktetemperatuur Europa 173 K, bepaald via λmax van infraroodspectrum$$, $$natuurkunde-havo-2021-i-de-maan-europa-context3.png$$, 501, $$De oppervlaktetemperatuur van Europa is 173 K. Dit is bepaald door λmax te meten van het infraroodspectrum dat deze maan uitzendt.$$, 'inline'),
  ('82179a37-8601-4f66-8be3-fed837943f44', '594a24dd-c80b-44f7-8939-652805725c80', $$figuur 2 — Jupiter en Europa met punten a en b$$, $$natuurkunde-havo-2021-i-de-maan-europa-context4.png$$, 501, $$Sommige wetenschappers denken dat de temperatuur onder het oppervlak van Europa veel hoger is dan 173 K. Hun verklaring hiervoor is de voortdurende verandering van de gravitatiekracht op de maan Europa. In figuur 2 zijn Jupiter en Europa getekend. Deze figuur is niet op schaal. Op de maan Europa zijn twee punten gemarkeerd met ''a'' en ''b''.

figuur 2: schema van Jupiter en Europa, met op Europa de punten a (dichtst bij Jupiter) en b (verst van Jupiter).$$, 'inline'),
  ('4a9cf01e-5997-4fca-98ba-34bd3d4b010c', '594a24dd-c80b-44f7-8939-652805725c80', $$figuur 3 — mogelijke vervorming van Europa (I en II)$$, $$natuurkunde-havo-2021-i-de-maan-europa-context5.png$$, 501, $$De gravitatiekracht die Jupiter op Europa uitoefent is in punt a niet even groot als in punt b. Hierdoor wordt Europa een beetje vervormd. Dit is schematisch weergegeven in figuur 3.

figuur 3: twee mogelijke vervormingen van Europa (met punten a en b) naast Jupiter: I een ellipsvorm met de lange as loodrecht op de lijn Jupiter-Europa, II een ellipsvorm met de lange as langs de lijn Jupiter-Europa.$$, 'inline'),
  ('35b3b4f8-1c62-43e7-8e23-93c30b3cfff7', '594a24dd-c80b-44f7-8939-652805725c80', $$figuur 4 en 5 — stand van Io, Europa en Ganymedes op t=0 en t=3,55 d$$, $$natuurkunde-havo-2021-i-de-maan-europa-context6.png$$, 501, $$Behalve Jupiter oefenen ook de manen Ganymedes en Io een (kleine) gravitatiekracht uit op Europa. Omdat deze drie manen ten opzichte van elkaar in beweging zijn, veranderen deze gravitatiekrachten steeds. De wetenschappers denken dat de maan Europa zo ''gekneed'' wordt. Hierbij zou dan warmte ontstaan waardoor de temperatuur in het inwendige van Europa kan stijgen.

In figuur 4 is de stand van de drie manen op een bepaald moment t = 0 weergegeven. Neem aan dat Jupiter stilstaat en dat de drie manen in een cirkelbaan in de aangegeven richting bewegen. Op t = 3,55 d heeft de maan Io 2,0 omwentelingen om Jupiter gemaakt en is de stand zoals in figuur 5. Figuur 4 en 5 zijn niet op schaal.

figuur 4: cirkelbanen van Io, Europa en Ganymedes om Jupiter met hun stand op t = 0.
figuur 5: cirkelbanen van Io, Europa en Ganymedes om Jupiter met hun stand op t = 3,55 d.$$, 'inline'),
  ('7489a7d3-df62-466c-a7f2-a150de8b7bd0', '594a24dd-c80b-44f7-8939-652805725c80', $$vergelijk resulterende kracht op Europa in figuur 5 met figuur 4$$, $$natuurkunde-havo-2021-i-de-maan-europa-context7.png$$, 501, $$Vergelijk de resulterende kracht op (het zwaartepunt van) Europa in figuur 5 met die in figuur 4.$$, 'inline'),
  ('4917b706-e7a1-44f4-ab75-3eae5d484b81', '594a24dd-c80b-44f7-8939-652805725c80', $$omlooptijdverhouding T(Io) : T(Europa) : T(Ganymedes) = 1 : 2 : 4$$, $$natuurkunde-havo-2021-i-de-maan-europa-context8.png$$, 501, $$De omlooptijden van de manen van Jupiter hebben een vaste verhouding tot elkaar. Er geldt: T(Io) : T(Europa) : T(Ganymedes) = 1 : 2 : 4.$$, 'inline'),
  ('b2938302-eefb-44c6-a56b-03608d78086e', '594a24dd-c80b-44f7-8939-652805725c80', $$figuur 4 en 5 ook op de uitwerkbijlage$$, $$natuurkunde-havo-2021-i-de-maan-europa-context9.png$$, 501, $$Figuur 4 en figuur 5 staan ook op de uitwerkbijlage.$$, 'inline'),
  ('87109f81-83e3-45b8-b728-694c84668efc', '594a24dd-c80b-44f7-8939-652805725c80', $$uitwerkbijlage vraag 12 — derde (lege) figuur om stand van manen op t=5,32 d te tekenen$$, $$natuurkunde-havo-2021-i-de-maan-europa-uitwerkbijlage-vraag12.png$$, 501, $$Uitwerkbijlage vraag 12: drie figuren met de cirkelbanen van Io, Europa en Ganymedes om Jupiter — de eerste twee tonen de stand op t = 0 en t = 3,55 d (met legenda 1 = baan Ganymedes, 2 = baan Europa, 3 = baan Io), in de derde (lege) figuur moet de stand op t = 5,32 d getekend worden; met invullijnen voor de berekening.$$, 'uitwerkbijlage'),
  ('02bcaaae-ae7a-48a1-a324-416ada6bab60', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$figuur 1 — kitmarker met tritium (H-3), β-straler; verflaag zendt licht uit (2,5 eV)$$, $$natuurkunde-havo-2021-i-kitmarker-context1.png$$, 501, $$Een kitmarker is een permanente lichtbron die aan een sleutelbos gehangen kan worden. Zie figuur 1. Zo zijn sleutels in het donker terug te vinden. Een kitmarker heeft geen batterij. Het is een glazen buisje met daarin gasvormig H-3 (tritium). Tritium is een β-straler.

figuur 1: foto van een kitmarker (lichtgevend buisje) aan een sleutelbos.

De binnenkant van de glazen buis is voorzien van een speciale verflaag. De vrijgekomen straling uit het tritiumverval zorgt ervoor dat de verflaag groenblauw licht gaat uitzenden. De fotonen van dit zichtbare licht hebben een energie van 2,5 eV.$$, 'inline'),
  ('ad2d51f6-41f2-42d1-a2ae-f1f91594a4f9', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$β-deeltjes passeren positieve kernen van tritium, richting baan verandert$$, $$natuurkunde-havo-2021-i-kitmarker-context2.png$$, 501, $$De uitgezonden β-deeltjes passeren de positieve kernen van het tritium. Hierbij verandert de richting van de baan van het β-deeltje.$$, 'inline'),
  ('f0219981-e170-416e-bc1f-62054e09acea', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$energie vrijgekomen foton 1,0·10⁻² MeV bij baanverandering β-deeltje$$, $$natuurkunde-havo-2021-i-kitmarker-context3.png$$, 501, $$Bij de verandering van de baan van een β-deeltje komt energie vrij. Deze energie komt vrij als een foton met een energie van 1,0·10⁻² MeV. Dit foton wordt ook door de kitmarker uitgezonden.$$, 'inline'),
  ('0cce6fab-13b3-4900-8f23-d3bb80667d81', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$figuur 2 — meetgrafiek intensiteit tegen dikte aluminium, vuistregel halveringsdikte weefsel = 10× aluminium$$, $$natuurkunde-havo-2021-i-kitmarker-context4.png$$, 501, $$Sleutels worden vaak meegenomen in een broekzak. De kitmarker wordt dan langdurig tegen het lichaam gedragen. Een onderzoeker wil het risico hiervan onderzoeken. Hij wil veilig de halveringsdikte voor deze fotonen in menselijk lichaamsweefsel bepalen. In plaats van menselijk weefsel gebruikt hij aluminium en hanteert hij daarbij de volgende vuistregel:

De halveringsdikte van menselijk lichaamsweefsel voor dit soort straling is 10 keer zo groot als de halveringsdikte van aluminium.

Achter aluminium plaatjes van diverse diktes meet de onderzoeker de intensiteit van de straling afkomstig van de kitmarker. Hij meet met een GM-teller het aantal pulsen per minuut. Zijn metingen zijn uitgezet in een diagram. Zie figuur 2.

figuur 2: grafiek van de intensiteit (pulsen per minuut, 0-7,0·10³) tegen de dikte aluminium in mm (0,0-2,5); dalende kromme van 6,0·10³ bij 0,0 mm naar circa 2,4·10³ bij 2,5 mm.

Ten slotte heeft hij de achtergrondstraling bepaald. Deze is 1,00·10³ pulsen per minuut. Figuur 2 is ook op de uitwerkbijlage weergegeven.$$, 'inline'),
  ('45148c48-0b30-47cb-9953-9d327794a65e', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$blootstelling 8,0 uur/dag, massa 1,5·10² g, 1,25·10³ fotonen/s, weegfactor 1, foton-energie 1,6·10⁻¹⁵ J, dosislimiet 50 mSv/jaar$$, $$natuurkunde-havo-2021-i-kitmarker-context5.png$$, 501, $$De onderzoeker neemt aan dat iemand de kitmarker 8,0 uur per dag in zijn zak heeft. De bestraalde lichaamsmassa is 1,5·10² gram. Deze massa absorbeert per seconde de energie van 1,25·10³ fotonen.
De weegfactor voor deze straling is 1. Ieder foton heeft een energie van 1,6·10⁻¹⁵ J. De equivalente dosislimiet voor dit deel van het lichaam is 50 mSv per jaar.$$, 'inline'),
  ('151a4393-5faf-4228-9920-0ab8d98aba51', '43f5c672-3b00-4d9b-9c3b-424b66d5cc15', $$uitwerkbijlage vraag 17 — figuur 2 herhaald met invulruimte voor bepaling halveringsdikte$$, $$natuurkunde-havo-2021-i-kitmarker-uitwerkbijlage-vraag17.png$$, 501, $$Uitwerkbijlage vraag 17: dezelfde grafiek als figuur 2 (intensiteit tegen dikte aluminium), gevolgd door invullijnen onder het kopje ''Bepaling:'' voor de uitwerking van de halveringsdikte.$$, 'uitwerkbijlage'),
  ('d1bf83f5-72aa-4c07-9453-043c8c4fdb3e', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$figuur 1 en 2 — sprong zonder parachute vanaf bijna 8 km, vangnet$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context1.png$$, 501, $$In 2016 sprong skydiver Luke Aikins zonder parachute vanaf een hoogte van bijna 8 km recht naar beneden. Boven de grond was een groot net opgespannen om hem veilig op te vangen. Zie figuur 1 en 2.

figuur 1: foto van Aikins tijdens de vrije val, van bovenaf gezien.
figuur 2: foto van het net, opgespannen tussen vier hijskranen boven een heuvellandschap.$$, 'inline'),
  ('0af56051-a439-41f9-9810-556c5b8a59e3', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$formule Fw = kAv², met k constante, A frontale oppervlakte, v snelheid t.o.v. lucht$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context2.png$$, 501, $$Aikins ondervond een luchtweerstandskracht. Hiervoor geldt: Fw = kAv².

Hierin is:
− k een constante;
− A de frontale oppervlakte van Aikins;
− v de snelheid ten opzichte van de lucht.$$, 'inline'),
  ('d6df6c89-4d7c-4862-87b7-8b5c20b87632', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$constante eindsnelheid 54 m/s, massa 75 kg, frontale oppervlakte 0,80 m²$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context3.png$$, 501, $$Dankzij de luchtweerstandskracht bereikte hij na verloop van tijd een constante snelheid van 54 m s⁻¹. Zijn massa is 75 kg en zijn frontale oppervlakte is 0,80 m².$$, 'inline'),
  ('ab394dab-7eef-448f-93bf-5e1be8b86970', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$laatste 1,0 km: valsnelheid 54 m/s, zijwind geeft horizontale snelheid 4,9 km/h$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context4.png$$, 501, $$Tijdens de laatste 1,0 kilometer op weg naar het net was Aikins'' valsnelheid 54 m s⁻¹. Ook was er zijwind die hem een constante horizontale snelheid zou geven van 4,9 km h⁻¹. Aikins moest tijdens zijn val daarom bijsturen op weg naar het net.$$, 'inline'),
  ('fb1f75b5-9dc9-4fab-9a9a-488b973d7ae7', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$figuur 3 en 4 — luchtweerstandskrachten op handen, draaipunt D, richtingen P en Q$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context5.png$$, 501, $$Een landing op de buik is gevaarlijk. Aikins moest daarom vlak voor de landing draaien. Dat deed hij door een van zijn handen dichter bij zijn lichaam te houden. In figuren 3 en 4 is dat weergegeven. Aikins wordt hierbij als stilstaand beschouwd, terwijl de bewegende lucht weerstandskracht op zijn beide handen uitoefent. Andere krachten worden niet meegenomen.

figuur 3: Aikins met beide armen gestrekt, draaipunt D in het midden, aangrijpingspunten van de luchtweerstandskrachten aan beide handen even ver van D.
figuur 4: Aikins met één hand dichter naar het lichaam gebogen, draaipunt D, richtingen P en Q aangegeven waarin Aikins kan gaan draaien.

Op beide handen werken even grote luchtweerstandskrachten. De werklijnen en aangrijpingspunten van deze krachten zijn weergegeven in de figuur. Aikins is hierbij in evenwicht.
Aikins buigt één hand dichter naar zich toe. De grootte van de luchtweerstandskrachten op zijn handen blijft constant. Hierdoor ontstaat een verschil in moment links en rechts. Als gevolg van het buigen begint Aikins te draaien rondom draaipunt D, in de richting van de kracht met het grootste moment.

Op de uitwerkbijlage staan figuren 3 en 4 en twee invulzinnen.$$, 'inline'),
  ('b76f2525-d49a-4b41-b3ce-db7f265cf14a', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$figuur 5 — videometing landing in het net (4 videobeelden)$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context6.png$$, 501, $$Van de landing in het net is een videometing gemaakt. Zie figuur 5.

figuur 5: vier opeenvolgende videobeelden (1 t/m 4) van Aikins die in het net landt, van vlak voor tot tijdens het doorzakken van het net.$$, 'inline'),
  ('fbcf59b3-e42d-4c93-9848-8ca93af1f03e', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$net remt af van 54 m/s tot stilstand, nog 37 m naar beneden afgelegd$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context7.png$$, 501, $$Het net remde Aikins af van 54 m s⁻¹ tot stilstand. Tijdens het afremmen legde Aikins nog 37 m naar beneden af. Verwaarloos de arbeid door de luchtwrijvingskracht tijdens het remmen.$$, 'inline'),
  ('aaf08d57-4448-4c6f-85bc-0d5a103631b6', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$tabel op uitwerkbijlage met ontwerpoplossingen en natuurkundige concepten$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context8.png$$, 501, $$Het net moest aan diverse eisen voldoen om Aikins veilig tot stilstand te brengen. Op de uitwerkbijlage staat een tabel met technische ontwerpoplossingen voor het net en natuurkundige concepten die daarbij een rol spelen.$$, 'inline'),
  ('1c1cc887-efc2-44d1-8ca4-4093a116db22', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$(v,t)-diagram afremmen in het net en diagram veilige vertragingsduur, op uitwerkbijlage$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-context9.png$$, 501, $$Op de uitwerkbijlage staat het (v,t)-diagram van het laatste deel van de stunt van Aikins: het afremmen in het net. Ook staat op de uitwerkbijlage een tweede diagram. In dit diagram is af te lezen gedurende hoeveel tijd een mens een bepaalde vertraging veilig kan ondergaan voordat deze vertraging schadelijk wordt.$$, 'inline'),
  ('d5418616-f958-41db-83a0-17b548b14a92', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$uitwerkbijlage vraag 22 — figuren 3 en 4 om krachten/armen in te tekenen, invulzinnen groter/kleiner en P/Q$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-uitwerkbijlage-vraag22.png$$, 501, $$Uitwerkbijlage vraag 22: figuur 3 en figuur 4 (Aikins met draaipunt D) om de luchtweerstandskrachten en bijbehorende armen in te tekenen, gevolgd door de invulzinnen ''Doordat Aikins één hand naar zich toe buigt, wordt het moment van de luchtweerstandskracht op die hand groter / kleiner.'' en ''Aikins begint hierdoor te draaien in de richting van P / Q.''$$, 'uitwerkbijlage'),
  ('062321dd-2aa4-42d4-9f21-06c976c629e6', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$uitwerkbijlage vraag 24 — tabel oplossing in ontwerp / natuurkundig concept$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-uitwerkbijlage-vraag24.png$$, 501, $$Uitwerkbijlage vraag 24: tabel met kolommen ''oplossing in ontwerp'' en ''natuurkundig concept''; rijen ''Het net is hoog opgehangen.'', ''Het net scheurt niet.'' en ''Het net veert niet terug.'', elk met de keuzemogelijkheden ''plastische vervorming / remafstand / treksterkte'' om te omcirkelen.$$, 'uitwerkbijlage'),
  ('5274ff4d-bc93-464e-a355-de3a7d7accb4', 'bd6f54e3-9271-4f2b-848a-820a7be2cb7b', $$uitwerkbijlage vraag 25 — (v,t)-diagram afremmen in net en grafiek maximale veilige vertraging$$, $$natuurkunde-havo-2021-i-sprong-van-luke-aikins-uitwerkbijlage-vraag25.png$$, 501, $$Uitwerkbijlage vraag 25: bovenste grafiek toont de snelheid v (m/s, 0-60) tegen de tijd (s, 87,2-89,0) tijdens het afremmen in het net, met v constant op 54 m/s tot circa t=87,5 s en dan afnemend tot 0 bij circa t=88,8 s. Onderste grafiek toont de maximale veilige vertraging (m/s², 0-150) tegen de veilige tijdsduur (s, 0-10): een sterk dalende kromme van circa 148 m/s² bij 0 s naar circa 48 m/s² bij 10 s.$$, 'uitwerkbijlage'),
  ('f3576b97-e536-400c-9a61-769725f6aec6', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$figuur 1 en 2 — cicade op een boom en op ware grootte in een hand$$, $$natuurkunde-havo-2021-i-cicaden-context1.png$$, 501, $$In het bos zijn in de zomer vaak cicaden te vinden. Zie figuur 1 en 2. Figuur 2 is hier op ware grootte.

figuur 1: foto van een cicade tegen een boomstam.
figuur 2: foto van een cicade op ware grootte, vastgehouden tussen twee vingers.$$, 'inline'),
  ('b1f1e29f-7054-4a48-85f7-c81dc81c10bf', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$mannetjes produceren hard geluid om vrouwtjes te zoeken$$, $$natuurkunde-havo-2021-i-cicaden-context2.png$$, 501, $$De mannetjes van deze insectensoort produceren een hard geluid om vrouwtjes te zoeken.$$, 'inline'),
  ('ef1ed5b5-a657-4fe4-aee5-b7697c3179fa', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$figuur 3 — tymbaal, aanspannen (in-klik) en ontspannen (uit-klik) van de spier$$, $$natuurkunde-havo-2021-i-cicaden-context3.png$$, 501, $$De mannetjes produceren het geluid door het afwisselend samentrekken en ontspannen van een spier, waardoor een zogenaamde tymbaal van vorm verandert. Bij het aanspannen van de spier veroorzaakt die vormverandering van de tymbaal kortstondig een geluidspuls (de ''in-klik''). Door de spier te ontspannen klapt de tymbaal weer terug en wordt opnieuw een korte geluidspuls gemaakt (de ''uit-klik''). Zie figuur 3.

figuur 3: drie tekeningen van de tymbaal — ontspannen spier (bolvormig omhoog), aanspannen spier: in-klik (naar binnen geklapt), ontspannen spier: uit-klik (weer naar boven geklapt).$$, 'inline'),
  ('94937c65-4f5f-4308-b3d9-7878145de5d7', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$figuur 4 — oscillogram geluid cicade met kloksignaal van 10 ms per piek$$, $$natuurkunde-havo-2021-i-cicaden-context4.png$$, 501, $$Van het geluid van een cicade is een oscillogram gemaakt. Zie figuur 4.

figuur 4: oscillogram met bovenaan het kloksignaal (pieken elke 10 ms) en onderaan het geluidssignaal van de cicade, met een korte trilling (in-klik) gevolgd door een grotere, geleidelijk uitdempende trilling (uit-klik).

In figuur 4 is opeenvolgend het patroon van de geluidspuls van de in-klik en van de uit-klik te zien.

Het oscillogram is gemaakt met een meetapparaat dat voor de tijdsregistratie gebruikmaakt van een klok. De klok produceert om de 10 ms een piek. Die pieken zijn ook weergeven in figuur 4. Deze figuur staat ook op de uitwerkbijlage.$$, 'inline'),
  ('7ebec0c4-f18b-4b0d-b5c1-c6e947f23fe3', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$geluid wordt versterkt door de buikholte$$, $$natuurkunde-havo-2021-i-cicaden-context5.png$$, 501, $$Het geluid wordt door de buikholte versterkt.$$, 'inline'),
  ('2908188d-af5c-4712-b710-5c551f039e71', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$amplitude van de trilling van de uit-klik neemt af$$, $$natuurkunde-havo-2021-i-cicaden-context6.png$$, 501, $$In figuur 4 is te zien dat de amplitude van de trilling van de uit-klik afneemt.$$, 'inline'),
  ('c2f387bc-7736-4c56-a918-4000467ced72', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$vrouwtje reageert met vleugels, bomen blokkeren geluid, temperatuur bos 30 °C$$, $$natuurkunde-havo-2021-i-cicaden-context7.png$$, 501, $$De mannetjescicaden maken dit geluid om vrouwtjes te vinden. Een vrouwtje reageert door geluid te maken met haar vleugels. In het bos kunnen bomen het geluid blokkeren als de golflengte van het geluid korter is dan de breedte van een boom. Bij een langere golflengte buigt het geluid om de boom heen en is het ook achter de boom te horen. De temperatuur in het bos is 30 °C.$$, 'inline'),
  ('4c0c5330-2846-47fb-88b1-6bb0ad14d222', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$uitwerkbijlage vraag 26 — invulzinnen staande/lopende golf en transversaal/longitudinaal$$, $$natuurkunde-havo-2021-i-cicaden-uitwerkbijlage-vraag26.png$$, 501, $$Uitwerkbijlage vraag 26: ''Het geluid gaat van een cicade-mannetje naar een cicade-vrouwtje via een staande / lopende golf in de lucht.'' en ''Deze golf is transversaal / longitudinaal.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('12ed6225-9873-4cf4-aa8e-3da0e79023bf', '18aaa64f-6011-4a2e-972d-712bc180dfaa', $$uitwerkbijlage vraag 27 — oscillogram figuur 4 herhaald$$, $$natuurkunde-havo-2021-i-cicaden-uitwerkbijlage-vraag27.png$$, 501, $$Uitwerkbijlage vraag 27: dezelfde oscillogram als figuur 4, met bovenaan het kloksignaal (pieken elke 10 ms) en onderaan het geluidssignaal met de in-klik en uit-klik.$$, 'uitwerkbijlage');

